action.code:
do {
    old_val = *bitmap_word;
    if (old_val == all_ones) continue to next word;
    new_val = old_val | (old_val + 1); // This sets the lowest unset bit
} while (!atomic_compare_exchange_weak(bitmap_word, &old_val, new_val));

